create table if not exists public.operations (id bigint generated by default as identity primary key, operation_date date not null default current_date, type text not null check (type in ('Доход','Расход')), category text not null, payment text, amount numeric not null check (amount>0), note text, created_at timestamptz default now()); alter table public.operations enable row level security; create policy "authenticated users manage operations" on public.operations for all to authenticated using (true) with check (true);